<td><form method="post" action="/admin/contacts"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int) $c['id'] ?>"><button class="rowbtn"><?= $c['subscribed'] ? '✓ Subscribed' : 'Not subscribed' ?></button></form></td>
<td><a class="rowbtn" href="<?= e(url('/admin/mail/compose', ['to' => $c['email']])) ?>">Email</a></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="5" class="muted center" style="padding:26px">No contacts.</td></tr><?php endif; ?></tbody></table></div><?= pager($pg, '/admin/contacts', ['q' => $s, 'filter' => $f]) ?></div>
