<form class="panel" method="post" action="/admin/contacts" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="import"><div class="panel-h">Import from CSV</div><div class="panel-b form"><p class="small muted mb0">Columns: email, name (a header row is fine).</p><input type="file" name="csv" accept=".csv,text/csv" required><?= a_in('Tag these contacts', 'tags', '') ?><?= a_check('I confirm everyone in this file has agreed to receive email from Donums', 'consent') ?><button class="btn btn-ghost btn-sm">Import</button></div></form></div></div>
